/// <summary>
/// Task 96965: Pricing POC Generate invoices for sales orders, validate account allocation.
/// As we are not using the pricing engine in FO and we will not have any discounts, created a new version of the DiscountClaimHelper class
/// so we can create claims from new custom tables METSalesLinePriceComponent and METSalesLinePriceComponentDetails loaded by PE
/// </summary>
public class METDiscountClaimHelper
{
    private SalesQty        invoiceQty;
    private ItemId          itemId;
    private InventDimId     inventDimId;
    private InvoiceId       invoiceId;
    private SalesLine       salesLine;
    private LedgerVoucher   ledgerVoucher;
    private Voucher         voucher;
    private TransDate       transdate;

    private LedgerJournalTable  ledgerJournalTableClaimAccrual;
    private Voucher             voucherClaimAccrual;
    private GUPParameters       gupParameters;

}

Method.Source:
public void setPostLinesParameters(
    LedgerVoucher   _ledgerVoucher,
    Voucher         _voucher = null,
    TransDate       _transdate = dateNull())
{
    this.ledgerVoucher  = _ledgerVoucher;
    this.voucher        = _voucher;
    this.transdate      = _transdate;
}

public void setDiscountPostParameters(
    SalesQty        _invoiceQty,
    ItemId          _itemId,
    InventDimId     _inventDimId,
    InvoiceId       _invoiceId,
    SalesLine       _salesLine)
{
    this.invoiceQty     = _invoiceQty;
    this.itemId         = _itemId;
    this.inventDimId    = _inventDimId;
    this.invoiceId      = _invoiceId;
    this.salesLine      = _salesLine;
}

    /// <summary>
    /// Distribute discount claim
    /// </summary>
    public void distributeDiscountClaim()
    {
        METComponentCode                    componentCode;
        GUPDiscountClaim                    gupDiscountClaim;
        METSalesLinePriceComponentDetail    salesLinePriceComponentDetail;
        METSalesLinePriceComponent          salesLinePriceComponent;
        LedgerDimensionDefaultAccount       claimOffsetAccount = GUPParameters::find().METDiscountClaimPostingOffsetDefaultLedgerDimension;
        RecordInsertList                    ledgerJournalTransRecordList = new RecordInsertList(tableNum(LedgerJournalTrans));
      
        while select salesLinePriceComponentDetail
              where salesLinePriceComponentDetail.VendorValue > 0
              join salesLinePriceComponent
             where salesLinePriceComponentDetail.InventTransId == salesLine.InventTransId
                && salesLinePriceComponent.InventTransId == salesLinePriceComponentDetail.InventTransId
                && salesLinePriceComponent.Component == salesLinePriceComponentDetail.Component
          exists join componentCode
                where componentCode.Component == salesLinePriceComponentDetail.Component
                   // Bug 215809: CB789 - Line Charges is posted twice for sales order invoices.
                   && componentCode.PriceComponent == METPriceComponent::Discounts
        {
            if (!this.isDiscountClaimSetupValid(salesLinePriceComponent))
            {
                continue;
            }

            boolean isClaimDistribution = salesLinePriceComponentDetail.isClaimDistribution();

            // accrual account same as the component code detail main account
            MainAccountNum accrualAccount = METComponentCodeDetail::getMainAccountId(salesLinePriceComponentDetail.Component, salesLinePriceComponentDetail.Code);
            LedgerDimensionDefaultAccount debitAccount = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountId(accrualAccount);

            gupDiscountClaim = this.findOrCeateDiscountClaim(salesLinePriceComponent, salesLinePriceComponentDetail);

            this.addDiscountClaimTrans(gupDiscountClaim.DiscountClaimId, debitAccount, salesLinePriceComponentDetail.VendorValue, salesLinePriceComponent.PriceCodeRef);

            // To avoid journal posting issue
            salesLinePriceComponentDetail.VendorValue = salesLinePriceComponentDetail.VendorValue ? salesLinePriceComponentDetail.VendorValue : salesLinePriceComponentDetail.Value;

            this.createClaimAccrualLedgerJournalTrans(invoiceQty * salesLinePriceComponentDetail.VendorValue, debitAccount, claimOffsetAccount, ledgerJournalTransRecordList);
        }

        ledgerJournalTransRecordList.insertDatabase();
    }

    /// <summary>
    /// Validates the discount claim setup for the specified price component.
    /// </summary>
    /// <param name = "_priceComponent">SalesLinePriceComponent</param>
    /// <returns>boolean</returns>
    public boolean isDiscountClaimSetupValid(METSalesLinePriceComponent _priceComponent)
    {
        boolean ret = false;

        InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(itemId, inventDimId);
        VendAccount claimVendorAccount = inventItemSalesSetup.GUPDiscountClaimVendorAccount;

        if (METVendTable::find(claimVendorAccount).VendStatus == MetVendStatus::Active)
        {
            METClaimSetup metclaimSetup;
            InventSiteId siteId = InventDim::find(inventDimId).InventSiteId;

            select firstonly ClaimType, RecId from metclaimSetup
            where metclaimSetup.SiteId == siteId
               && metclaimSetup.Component == _priceComponent.Component
               && metclaimSetup.Supplier == claimVendorAccount;

            // Supplier Claim Setup, where Site = blank, will signify that the values for supplier/claim type and fee apply to all sites in the Legal Entity.
            // This will reduce the number of rows of data required for ALM as all suppliers have the same claim type in each site and they do not use the Admin Fee (Food only)
            if(!metclaimSetup.RecId)
            {
                select firstonly ClaimType, RecId from metclaimSetup
               where metclaimSetup.Component == _priceComponent.Component
                  && metclaimSetup.Supplier == claimVendorAccount
                  && metclaimSetup.SiteId == '';
            }

            if (metclaimSetup.RecId)
            {
                ret = true;
            }
        }

        return ret;
    }

    public void postDiscountClaimAccrualJournal()
    {
        if (LedgerJournalTableClaimAccrual)
        {
            LedgerJournalPost::postJournal(LedgerJournalTableClaimAccrual, NoYes::No);

            if (ledgerVoucher)
            {
                this.addLedgerTransVoucherLinkFromLedgerVoucher();
            }
            else
            {
                this.addLedgerTransVoucherLinkFromVoucher(voucher, transDate);
            }
        }
    }

    private void addLedgerTransVoucherLinkFromLedgerVoucher()
    {
        LedgerVoucherObject ledgerVoucherObject = ledgerVoucher.findLedgerVoucherObject();
        Voucher currentVoucher = ledgerVoucherObject.parmSubledgerVoucher();
        TransDate currentTransDate = ledgerVoucherObject.parmTransDate();

        this.addLedgerTransVoucherLinkFromVoucher(currentVoucher, currentTransDate);
    }

    private void addLedgerTransVoucherLinkFromVoucher(Voucher _currentVoucher, TransDate _currentTransDate)
    {
        LedgerTransVoucherLink ledgerTransVoucherLink;

        RecId voucherGroupId = LedgerTransVoucherLink::findVoucherGroupId(_currentVoucher, _currentTransDate);

        if (voucherGroupId == 0)
        {
            ledgerTransVoucherLink.clear();
            ledgerTransVoucherLink.Voucher = _currentVoucher;
            ledgerTransVoucherLink.TransDate = _currentTransDate;
            ledgerTransVoucherLink.insert();

            // The record ID of the first link record is used as the voucher group ID
            voucherGroupId = ledgerTransVoucherLink.RecId;

            // Setting the voucher group ID requires an update after the insert
            ledgerTransVoucherLink.selectForUpdate(true);
            ledgerTransVoucherLink.VoucherGroupId = voucherGroupId;
            ledgerTransVoucherLink.update();
        }

        ledgerTransVoucherLink.clear();
        ledgerTransVoucherLink.VoucherGroupId = voucherGroupId;
        ledgerTransVoucherLink.Voucher = voucherClaimAccrual;
        ledgerTransVoucherLink.TransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        ledgerTransVoucherLink.insert();
    }

    //private int getClaimDistributionCount(RetailSalesDiscountLine _SalesDiscountLine)
    private int getClaimDistributionCount()
    {
        /*GUPDiscountClaimDistribution claimDistribution;

        select count(RecId) from claimDistribution
            where claimDistribution.RefTableId == _SalesDiscountLine.RefTableId
               && claimDistribution.RefRecId   == _SalesDiscountLine.RefRecId
               && (claimDistribution.PostingProfileType == GUPDiscountClaimPostingProfileType::Claim
                || claimDistribution.PostingProfileType == GUPDiscountClaimPostingProfileType::NonClaim);

        return int642int(claimDistribution.RecId);*/
        METSalesLinePriceComponentDetail salesLinePriceComponentDetail;

        select count(RecId) from salesLinePriceComponentDetail
            where salesLinePriceComponentDetail.InventTransId == salesLine.InventTransId;
            //&& (salesLinePriceComponentDetail.Type == METComponentDetailClaimType::Claim
            //    || salesLinePriceComponentDetail.Type == METComponentDetailClaimType::NonClaim);

        return int642int(salesLinePriceComponentDetail.RecId);
    }

    /// <summary>
    /// Reuse GUPDiscountClaim for POC
    /// </summary>
    /// <param name = "_discountOfferId"></param>
    /// <param name = "_claimType"></param>
    /// <returns></returns>
    // private GUPDiscountClaim findOrCeateDiscountClaim(RetailPeriodicDiscountOfferId _discountOfferId, GUPDiscountClaimPostingProfileType _claimType)
    private GUPDiscountClaim findOrCeateDiscountClaim(METSalesLinePriceComponent _priceComponent, METSalesLinePriceComponentDetail _priceComponentDetails)
    {
        GUPDiscountClaim gupDiscountClaim;

        // POC find claimVendorAccount in METClaimSetup
        InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(itemId, inventDimId);
        VendAccount claimVendorAccount = inventItemSalesSetup.GUPDiscountClaimVendorAccount;
        METClaimSetup metclaimSetup;
        InventSiteId siteId = InventDim::find(inventDimId).InventSiteId;
        select firstonly ClaimType, RecId from metclaimSetup
            where metclaimSetup.SiteId == siteId
               && metclaimSetup.Component == _priceComponent.Component
               && metclaimSetup.Supplier == claimVendorAccount;

        // Supplier Claim Setup, where Site = blank, will signify that the values for supplier/claim type and fee apply to all sites in the Legal Entity. 
        // This will reduce the number of rows of data required for ALM as all suppliers have the same claim type in each site and they do not use the Admin Fee (Food only)
        if(!metclaimSetup.RecId)
        {
            select firstonly ClaimType, RecId from metclaimSetup
               where metclaimSetup.Component == _priceComponent.Component
                  && metclaimSetup.Supplier == claimVendorAccount
                  && metclaimSetup.SiteId == '';
        }

        GUPDiscountClaimId claimId;

        LedgerJournalId journalNum = this.getOrCreateClaimAccrualLedgerJournalTable().JournalNum;

        // Claim vendor account is not set.
        if (!claimVendorAccount)
        {
            warning(strFmt("@GlobalUnifiedPricing:VendorAccountForClaimNotSetOnItem", itemId));
            throw error("@SYS21533");
        }

        select firstonly DiscountId, DiscountClaimId, ClaimType, RecId from gupDiscountClaim
            where gupDiscountClaim.SalesInvoice      == invoiceId
               && gupDiscountClaim.DiscountId        == _priceComponent.PriceCodeRef//_discountOfferId
               && gupDiscountClaim.VendorAccount     == claimVendorAccount
               && gupDiscountClaim.AccrualJournalNum == journalNum
               && gupDiscountClaim.ClaimType         == GUPDiscountClaimPostingProfileType::Claim//_claimType
               && gupDiscountClaim.CurrencyCode      == salesLine.CurrencyCode
               && gupDiscountClaim.Status            == GUPDiscountClaimStatus::Calculated;

        // If there is already a claim created for this, add transactions to it without creating new claim.
        if (!gupDiscountClaim.RecId)
        {
            gupDiscountClaim.DiscountClaimId   = NumberSeq::newGetNum(GUPParameters::numRefDiscountClaimId()).num();
            gupDiscountClaim.DiscountId        = _priceComponent.PriceCodeRef;//_discountOfferId;
            gupDiscountClaim.VendorAccount     = claimVendorAccount;
            gupDiscountClaim.SalesInvoice      = invoiceId;
            gupDiscountClaim.AccrualJournalNum = journalNum;
            gupDiscountClaim.ClaimType         = GUPDiscountClaimPostingProfileType::Claim;//_claimType;
            gupDiscountClaim.CurrencyCode      = salesLine.CurrencyCode;
            gupDiscountClaim.Status            = GUPDiscountClaimStatus::Calculated;

            // CB790_DiscountClaim populate newly added fields            
            gupDiscountClaim.METInventSiteId   = siteId;
            gupDiscountClaim.METComponent      = _priceComponentDetails.Component;
            gupDiscountClaim.METClaimType      = metclaimSetup.ClaimType;
            gupDiscountClaim.METDiscountEndDate= _priceComponentDetails.ToDate;

            CustInvoiceJour custInvoiceJour;

            select firstonly InvoiceDate from custInvoiceJour
                where custInvoiceJour.InvoiceId == invoiceId
                    && custInvoiceJour.SalesId == salesLine.SalesId;

            gupDiscountClaim.METInvoiceDate    = custInvoiceJour.InvoiceDate;

            gupDiscountClaim.insert();
        }

        return gupDiscountClaim;
    }

    /// <summary>
    /// Reuse GUPParameters for POC
    /// </summary>
    /// <returns></returns>
    private LedgerJournalTable getOrCreateClaimAccrualLedgerJournalTable()
    {
        if (!ledgerJournalTableClaimAccrual)
        {
            if (!gupParameters.DiscountClaimAccrualJournal)
            {
                warning("@GlobalUnifiedPricing:DiscountClaimAccrualJournalError");
                throw error("@SYS21533");
            }

            LedgerJournalName ledgerJournalName = LedgerJournalName::find(gupParameters.DiscountClaimAccrualJournal);
            ledgerJournalTableClaimAccrual = ledgerJournalTableClaimAccrual.pdsInitFromledgerJournalName(ledgerJournalName);
            ledgerJournalTableClaimAccrual.insert();
        }

        return ledgerJournalTableClaimAccrual;
    }

    private void addDiscountClaimTrans(GUPDiscountClaimId _claimId, LedgerDimensionAccount _accrualAccount, Amount _amount, METPriceCodeRef _priceCodeRef)
    {
        GUPDiscountClaimTransaction gupDiscountClaimTransaction;

        // If there is already a claim transaction for this inventTransId, only add claim amount to it.
        select firstonly forupdate RecId, Amount from gupDiscountClaimTransaction
            where gupDiscountClaimTransaction.DiscountClaimId == _claimId
               && gupDiscountClaimTransaction.LedgerAccount   == _accrualAccount
               && gupDiscountClaimTransaction.InventTransId   == salesLine.InventTransId;

        if (!gupDiscountClaimTransaction.RecId)
        {
            gupDiscountClaimTransaction.DiscountClaimId  = _claimId;
            gupDiscountClaimTransaction.LedgerAccount    = _accrualAccount;
            gupDiscountClaimTransaction.Amount           = invoiceQty * _amount;
            gupDiscountClaimTransaction.ItemNumber       = salesLine.ItemId;
            gupDiscountClaimTransaction.InventTransId    = salesLine.InventTransId;
            gupDiscountClaimTransaction.DefaultDimension = salesLine.DefaultDimension;

            // CB790_DiscountClaim
            // Amount field from vendor value
            gupDiscountClaimTransaction.METDealAmount = _amount;
            gupDiscountClaimTransaction.METPriceCodeRef = _priceCodeRef;
        }
        else
        {
            gupDiscountClaimTransaction.Amount += invoiceQty * _amount;
            gupDiscountClaimTransaction.METDealAmount += _amount;
        }

        //  CB 790 Appendix C - GST Amount on Discount Claim
        gupDiscountClaimTransaction.METGSTAmount = Tax::calcTaxAmount(salesLine.TaxGroup, 
                                                                      salesLine.TaxItemGroup,
                                                                      DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                                                      salesLine.CurrencyCode,
                                                                      gupDiscountClaimTransaction.Amount,
                                                                      salesLine.salesTable().taxModuleType());

        gupDiscountClaimTransaction.write();
    }

    private void createClaimAccrualLedgerJournalTrans(AmountCur _amount, LedgerDimensionAccount _account, LedgerDimensionAccount _offsetAccount, RecordInsertList _ledgerJournalTransRecordList)
    {
        LedgerJournalTrans ledgerJournalTrans;
        boolean isPositiveAmount = _amount >= 0;
        date today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        ledgerJournalTrans.initValue();
        ledgerJournalTrans.JournalNum = this.getOrCreateClaimAccrualLedgerJournalTable().JournalNum;
        ledgerJournalTrans.Voucher = this.getOrCreateClaimAccrualJournalVoucher();
        ledgerJournalTrans.Txt = "@GlobalUnifiedPricing:DiscountClaimAccrual";
        ledgerJournalTrans.AmountCurDebit = isPositiveAmount ? _amount : 0;
        ledgerJournalTrans.AmountCurCredit = isPositiveAmount ? 0 : -_amount;
        ledgerJournalTrans.Approved = NoYes::Yes;
        ledgerJournalTrans.Approver = HcmWorker::userId2Worker(curUserId());
        ledgerJournalTrans.DocumentDate = today;
        ledgerJournalTrans.TransDate = today;
        ledgerJournalTrans.CurrencyCode = salesLine.CurrencyCode;
        // Bug 189743: CB789- Financial dimension combination error while posting the Sales invoice
        // add SO line default dimension to offset/ledger dimension as required by the Metcash account structure
        //ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_account);
        //ledgerJournalTrans.OffsetLedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_offsetAccount);
        ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_account, salesLine.DefaultDimension);
        ledgerJournalTrans.OffsetLedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_offsetAccount, salesLine.DefaultDimension);
        ledgerJournalTrans.ExchRate = ExchangeRateHelper::exchRate(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
        ledgerJournalTrans.ExchRateSecond = ExchangeRateHelper::exchRateSecond(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);

        _ledgerJournalTransRecordList.add(ledgerJournalTrans);
    }

    private Voucher getOrCreateClaimAccrualJournalVoucher()
    {
        if (!voucherClaimAccrual)
        {
            LedgerJournalName ledgerJournalName = LedgerJournalName::find(gupParameters.DiscountClaimAccrualJournal);
            NumberSequenceTable numberSequenceTable = NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable);
            NumberSeq numberSeq = NumberSeq::newGetVoucherFromCode(numberSequenceTable.NumberSequence, NumberSeqScopeFactory::createDefaultScope(), false);
            voucherClaimAccrual = numberSeq.voucher();
        }

        return voucherClaimAccrual;
    }
